  UmaReference *entry=&scene->reference[i];if(memcmp(&entry->key,key,sizeof(*key)))continue;
  for(int r=0;r<4;r++)for(int c=0;c<3;c++)if(fabsf(entry->matrix.m[r][c]-matrix->m[r][c])>.003f)entry->ambiguous=1;
